class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def removeListedValues(nums, banned):
    bad = set(banned)
    dummy = ListNode(0, build(nums))
    prev, cur = dummy, dummy.next
    while cur:
        if cur.val in bad:
            prev.next = cur.next
        else:
            prev = cur
        cur = cur.next
    return dump(dummy.next)
